server.tool(
  "get_linkedin_posts",
  `Fetch AQ-relevant LinkedIn posts for an organisation.
   Searches 21 AQ keywords via the company's profile and filters by date range.
   If li_handle is a /in/ URL it fetches a person profile; /company/ fetches a company page.`,
  {
    li_handle: external_exports.string().describe("LinkedIn handle, company URL, or person URL. E.g. 'wri-india', 'https://linkedin.com/company/ceew'"),
    date_from: external_exports.string().describe("YYYY-MM-DD"),
    date_to: external_exports.string().describe("YYYY-MM-DD"),
    keywords: external_exports.array(external_exports.string()).optional().describe("Extra AQ keywords beyond the default 21")
  },
  async ({ li_handle, date_from, date_to, keywords }) => {
    const apiKey = cfg().APIDIRECT_KEY;
    if (!apiKey) return { content: [{ type: "text", text: "ERROR: APIDIRECT_KEY not configured" }], isError: true };
    callTracker.apidirectCalls++;
    const AQ_KEYWORDS = [
      "ncap",
      "policy regulations",
      "pm2.5",
      "stubble burning",
      "clean air finance",
      "vehicular pollution",
      "health impact",
      "industrial pollution",
      "heat-aqi",
      "brick kiln",
      "petrol emission",
      "diesel emission",
      "super emitter",
      "thermal power",
      "household pollution",
      "indoor pollution",
      "biomass",
      "rice residue",
      "wheat residue",
      "road dust",
      "air quality",
      ...keywords ?? []
    ];
    const handle = li_handle.replace(/^@/, "").trim();
    const isPersonUrl = handle.includes("/in/") && !handle.includes("/company/");
    const companyUrl = handle.startsWith("http") ? handle : `https://www.linkedin.com/company/${handle}`;
    const profileUrl = handle.startsWith("http") ? handle : `https://www.linkedin.com/in/${handle}`;
    let filterParam = {};
    if (!isPersonUrl) {
      const r = await apidirectGet("linkedin/company", { url: companyUrl });
      if (!r.ok) {
        return { content: [{ type: "text", text: `Could not resolve company: ${JSON.stringify(r.data)}` }], isError: true };
      }
      const companyId = r.data?.company_id;
      if (!companyId) return { content: [{ type: "text", text: "No company_id returned from APIdirect" }], isError: true };
      filterParam = { from_company: String(companyId) };
    } else {
      filterParam = { author: profileUrl };
    }
    const seen = /* @__PURE__ */ new Map();
    for (const keyword of AQ_KEYWORDS) {
      for (let page = 1; page <= 3; page++) {
        const r = await apidirectGet("linkedin/posts", { query: keyword, sort_by: "most_recent", page, ...filterParam });
        if (!r.ok) break;
        const posts2 = r.data?.posts ?? [];
        if (!posts2.length) break;
        for (const post of posts2) {
          if (!inRange(post.date, date_from, date_to)) continue;
          const key = String(post.url ?? `${post.date}:${String(post.snippet ?? "").slice(0, 80)}`);
          if (!seen.has(key)) seen.set(key, { ...post, keywords_found: [] });
          seen.get(key).keywords_found.push(keyword);
        }
        const oldest = posts2.map((p) => parseDate(p.date)).filter(Boolean).sort((a, b) => +a - +b)[0];
        if (date_from && oldest && oldest < new Date(date_from)) break;
      }
    }
    const posts = [...seen.values()];
    const totalLikes = posts.reduce((s, p) => s + (Number(p.likes) || 0), 0);
    const totalComments = posts.reduce((s, p) => s + (Number(p.comments) || 0), 0);
    const totalShares = posts.reduce((s, p) => s + (Number(p.shares) || 0), 0);
    const topPosts = posts.sort(
      (a, b) => Number(b.likes) + Number(b.comments) + Number(b.shares) - (Number(a.likes) + Number(a.comments) + Number(a.shares))
    ).slice(0, 5);
    return {
      content: [{
        type: "text",
        text: JSON.stringify({
          postCount: posts.length,
          totalLikes,
          totalComments,
          totalShares,
          totalEngagement: totalLikes + totalComments + totalShares,
          topPosts
        }, null, 2)
      }]
    };
  }
);
server.tool(
  "get_twitter_posts",
  "Fetch AQ-relevant Twitter/X posts for an organisation. Provide twitter_handle if known; otherwise provide org_name and the tool will search for the handle.",
  {
    twitter_handle: external_exports.string().optional().describe("Twitter/X username without @, e.g. 'WRIIndia'. Omit if unknown \u2014 provide org_name instead."),
    org_name: external_exports.string().optional().describe("Full organisation name (e.g. 'WRI India') used to auto-find the Twitter handle when twitter_handle is not known."),
    date_from: external_exports.string().describe("YYYY-MM-DD"),
    date_to: external_exports.string().describe("YYYY-MM-DD"),
    keywords: external_exports.array(external_exports.string()).optional().describe("AQ keywords to filter by")
  },
  async ({ twitter_handle, org_name, date_from, date_to, keywords }) => {
    const apiKey = cfg().APIDIRECT_KEY;
    if (!apiKey) return { content: [{ type: "text", text: "ERROR: APIDIRECT_KEY not configured" }], isError: true };
    callTracker.apidirectCalls++;
    let handle = twitter_handle?.replace(/^@/, "").trim();
    if (!handle) {
      if (!org_name) return { content: [{ type: "text", text: "ERROR: Provide either twitter_handle or org_name" }], isError: true };
      const sr = await apidirectGet("twitter/users/search", { q: `${org_name} india air quality`, limit: "3" });
      const users = sr.data?.users ?? [];
      handle = users[0] ? String(users[0].username ?? "") : "";
      if (!handle) {
        const fk = cfg().FIRECRAWL_KEY;
        if (fk) {
          const fr = await apiFetch("https://api.firecrawl.dev/v2/search", {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${fk}` },
            body: JSON.stringify({ query: `"${org_name}" Twitter X handle @`, limit: 3 })
          });
          const hits = fr.data?.data ?? [];
          const snippet = hits.map((h) => h.description ?? h.title ?? "").join(" ");
          const m = String(snippet).match(/@([A-Za-z0-9_]{3,50})/);
          if (m) handle = m[1];
        }
        if (!handle) return { content: [{ type: "text", text: `Could not find Twitter handle for "${org_name}". Please provide it explicitly as twitter_handle.` }] };
      }
    }
    const aqKw = keywords ?? [
      "air quality",
      "air pollution",
      "aqi",
      "pm2.5",
      "pm10",
      "ncap",
      "grap",
      "smog",
      "clean air",
      "particulate",
      "emission",
      "Black Carbon",
      "Ozone",
      "Ammonia",
      "Carbon Monoxide",
      "Nitrogen Dioxide",
      "Methane"
    ];
    const kwClause = aqKw.map((k) => k.includes(" ") ? `"${k}"` : k).join(" OR ");
    const query = `from:@${handle} (${kwClause}) -is:retweet`;
    const [userR, firstR] = await Promise.allSettled([
      apidirectGet("twitter/user", { username: handle }),
      apidirectGet("twitter/posts", { query, page: 1 })
    ]);
    const followers = userR.status === "fulfilled" ? userR.value.data?.user?.followers_count ?? 0 : 0;
    if (firstR.status === "rejected") {
      return { content: [{ type: "text", text: `Twitter fetch failed: ${firstR.reason}` }], isError: true };
    }
    let all = firstR.value.data?.tweets ?? firstR.value.data?.posts ?? [];
    for (let page = 2; page <= 5; page++) {
      const r = await apidirectGet("twitter/posts", { query, page });
      const batch = r.data?.tweets ?? r.data?.posts ?? [];
      if (!batch.length) break;
      all = all.concat(batch);
      const oldest = batch.map((p) => parseDate(p.date ?? p.created_at)).filter(Boolean).sort((a, b) => +a - +b)[0];
      if (date_from && oldest && oldest < new Date(date_from)) break;
    }
    const tweets = all.filter((t) => inRange(t.date ?? t.created_at, date_from, date_to));
    const totalLikes = tweets.reduce((s, t) => s + (Number(t.likes) || 0), 0);
    const totalReplies = tweets.reduce((s, t) => s + (Number(t.replies) || 0), 0);
    const totalRetweets = tweets.reduce((s, t) => s + (Number(t.retweets) || 0), 0);
    const totalViews = tweets.reduce((s, t) => s + (Number(t.views) || 0), 0);
    const totalEngage = totalLikes + totalReplies + totalRetweets;
    const er = followers > 0 && tweets.length > 0 ? +(totalEngage / tweets.length / followers * 100).toFixed(3) : 0;
    return {
      content: [{
        type: "text",
        text: JSON.stringify({
          postCount: tweets.length,
          followers,
          er,
          totalLikes,
          totalReplies,
          totalRetweets,
          totalViews,
          topPosts: tweets.sort(
            (a, b) => Number(b.likes) + Number(b.replies) + Number(b.retweets) - (Number(a.likes) + Number(a.replies) + Number(a.retweets))
          ).slice(0, 5)
        }, null, 2)
      }]
    };
  }
);
server.tool(
  "get_instagram_posts",
  "Fetch AQ-relevant Instagram posts for an organisation. Provide ig_handle if known; otherwise provide org_name and the tool will search for it.",
  {
    ig_handle: external_exports.string().optional().describe("Instagram username without @, e.g. 'wriafrica'. Omit if unknown \u2014 provide org_name instead."),
    org_name: external_exports.string().optional().describe("Full organisation name used to auto-find the Instagram handle when ig_handle is not known."),
    date_from: external_exports.string().describe("YYYY-MM-DD"),
    date_to: external_exports.string().describe("YYYY-MM-DD"),
    keywords: external_exports.array(external_exports.string()).optional().describe("AQ keywords to filter relevance")
  },
  async ({ ig_handle, org_name, date_from, date_to, keywords }) => {
    const apiKey = cfg().APIDIRECT_KEY;
    if (!apiKey) return { content: [{ type: "text", text: "ERROR: APIDIRECT_KEY not configured" }], isError: true };
    callTracker.apidirectCalls++;
    let handle = ig_handle?.replace(/^@/, "").trim();
    if (!handle) {
      if (!org_name) return { content: [{ type: "text", text: "ERROR: Provide either ig_handle or org_name" }], isError: true };
      const sr = await apidirectGet("instagram/users/search", { q: `${org_name} india`, limit: "3" });
      const users = sr.data?.users ?? [];
      handle = users[0] ? String(users[0].username ?? "") : "";
      if (!handle) return { content: [{ type: "text", text: `Could not find Instagram handle for "${org_name}". Please provide it explicitly as ig_handle.` }] };
    }
    const aqKw = keywords ?? [
      "ncap",
      "policy regulations",
      "pm2.5",
      "stubble burning",
      "clean air finance",
      "vehicular pollution",
      "health impact",
      "industrial pollution",
      "heat-aqi",
      "brick kiln",
      "petrol emission",
      "diesel emission",
      "super emitter",
      "thermal power",
      "household pollution",
      "indoor pollution",
      "biomass",
      "rice residue",
      "wheat residue",
      "road dust",
      "air quality"
    ];
    const [postsR, userR] = await Promise.allSettled([
      apidirectGet("instagram/user/posts", { username: handle, pages: 10 }),
      apidirectGet("instagram/user", { username: handle })
    ]);
    const followers = userR.status === "fulfilled" ? userR.value.data?.user?.follower_count ?? 0 : 0;
    if (postsR.status === "rejected") {
      return { content: [{ type: "text", text: `Instagram fetch failed: ${postsR.reason}. Followers known: ${followers}` }], isError: true };
    }
    const allPosts = postsR.value.data?.posts ?? [];
    const inDatePosts = allPosts.filter((p) => inRange(p.date, date_from, date_to));
    const aqPosts = inDatePosts.filter((p) => {
      const txt = `${p.snippet ?? ""} ${p.title ?? ""}`.toLowerCase();
      return aqKw.some((k) => txt.includes(k.toLowerCase()));
    });
    const totalLikes = aqPosts.reduce((s, p) => s + (Number(p.likes) || 0), 0);
    const totalComments = aqPosts.reduce((s, p) => s + (Number(p.comments) || 0), 0);
    const totalEngage = totalLikes + totalComments;
    const er = followers > 0 && aqPosts.length > 0 ? +(totalEngage / aqPosts.length / followers * 100).toFixed(3) : 0;
    return {
      content: [{
        type: "text",
        text: JSON.stringify({
          postCount: aqPosts.length,
          followers,
          er,
          totalLikes,
          totalComments,
          fetched: allPosts.length,
          inRange: inDatePosts.length,
          topPosts: aqPosts.sort(
            (a, b) => Number(b.likes) + Number(b.comments) - (Number(a.likes) + Number(a.comments))
          ).slice(0, 5)
        }, null, 2)
      }]
    };
  }
);
