  const orgCount = orgs.length || 1;
  const months = dateMatch ? Math.max(1, Math.round(
    (new Date(dateMatch[2]).getTime() - new Date(dateMatch[1]).getTime()) / (30.44 * 24 * 3600 * 1e3)
  )) : 1;
  const billingMin = orgCount * months * 47;
  const billingMax = orgCount * months * 49;
  const orgList = orgs.length ? orgs.join(", ") : slug;
  const fcSearchCost = +(counts.firecrawlSearches * COST.FC_SEARCH).toFixed(3);
